WIDGET_SHIFT_INFO_XML = '<?xml version="1.0" encoding="utf-8"?>\n<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"\n    android:id="@+id/widgetRoot"\n    android:layout_width="match_parent"\n    android:layout_height="match_parent"\n    android:background="@drawable/bg_widget_card"\n    android:gravity="center_vertical"\n    android:orientation="horizontal"\n    android:paddingStart="12dp"\n    android:paddingEnd="10dp"\n    android:paddingTop="8dp"\n    android:paddingBottom="8dp">\n\n    <LinearLayout\n        android:id="@+id/widgetInfoArea"\n        android:layout_width="0dp"\n        android:layout_height="wrap_content"\n        android:layout_weight="1"\n        android:orientation="vertical"\n        android:paddingEnd="8dp">\n\n        <TextView\n            android:id="@+id/widgetStatus"\n            android:layout_width="match_parent"\n            android:layout_height="wrap_content"\n            android:ellipsize="end"\n            android:maxLines="1"\n            android:text="Vuorovahti"\n            android:textColor="#38BDF8"\n            android:textSize="11sp"\n            android:textStyle="bold" />\n\n        <TextView\n            android:id="@+id/widgetShiftMain"\n            android:layout_width="match_parent"\n            android:layout_height="wrap_content"\n            android:layout_marginTop="2dp"\n            android:ellipsize="end"\n            android:maxLines="1"\n            android:text="Ei tulevia vuoroja"\n            android:textColor="#F1F5F9"\n            android:textSize="14sp"\n            android:textStyle="bold" />\n\n        <TextView\n            android:id="@+id/widgetShiftSub"\n            android:layout_width="match_parent"\n            android:layout_height="wrap_content"\n            android:layout_marginTop="1dp"\n            android:ellipsize="end"\n            android:maxLines="1"\n            android:text="Avaa sovellus synkronoidaksesi"\n            android:textColor="#94A3B8"\n            android:textSize="11.5sp" />\n    </LinearLayout>\n\n    <TextView\n        android:id="@+id/widgetBtnStamp"\n        android:layout_width="wrap_content"\n        android:layout_height="40dp"\n        android:minWidth="82dp"\n        android:background="@drawable/bg_notif_btn_in"\n        android:gravity="center"\n        android:paddingStart="12dp"\n        android:paddingEnd="12dp"\n        android:text="SISÄÄN"\n        android:textColor="#FFFFFF"\n        android:textSize="12sp"\n        android:textStyle="bold" />\n</LinearLayout>\n'

