def find_file(filename: str) -> Path | None:
    candidates = [
        Path("app/src/main/java/fi/numeron/vuorovahti") / filename,
        Path("src/main/java/fi/numeron/vuorovahti") / filename,
        Path("app/src/main/res/layout") / filename,
        Path("src/main/res/layout") / filename,
        Path("app/src/main/res/drawable") / filename,
        Path("src/main/res/drawable") / filename,
        Path("app/src/main/res/xml") / filename,
        Path("src/main/res/xml") / filename,
        Path("app/src/main") / filename,
        Path("src/main") / filename,
        Path("app") / filename,
        Path(filename),
    ]
    for c in candidates:
        if c.exists():
            return c
    for p in Path(".").rglob(filename):
        if ".git" not in p.parts and "build" not in p.parts:
            return p
    return None


def read_text_keep_nl(path: Path) -> tuple[str, str]:
    raw = path.read_bytes().decode("utf-8")
    newline = "\r\n" if "\r\n" in raw else "\n"
    return raw.replace("\r\n", "\n"), newline


def write_text_keep_nl(path: Path, content: str, newline: str) -> None:
    normalized = content.replace("\r\n", "\n")
    if newline == "\r\n":
        normalized = normalized.replace("\n", "\r\n")
    path.write_bytes(normalized.encode("utf-8"))


def write_file_exact(path: Path, content: str, label: str) -> bool:
    normalized = content.replace("\r\n", "\n").lstrip("\n")
    if not normalized.endswith("\n"):
        normalized += "\n"
    if path.exists():
        existing, nl = read_text_keep_nl(path)
        if existing == normalized:
            print(f"  [OK - jo ajantasalla] {label} ({path})")
            return False
        write_text_keep_nl(path, normalized, nl)
        print(f"  [PÄIVITETTY] {label} ({path})")
        return True
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(normalized.encode("utf-8"))
    print(f"  [LUOTU] {label} ({path})")
    return True


def replace_once(content: str, old: str, new: str, label: str) -> str:
    if new and new in content:
        print(f"  [OK - jo sovellettu] {label}")
        return content
    if old not in content:
        print(f"  [VAROITUS - kohdetta ei löytynyt] {label}")
        return content
    print(f"  [PÄIVITETTY] {label}")
    return content.replace(old, new, 1)


def patch_android_manifest(path: Path) -> bool:
    text, nl = read_text_keep_nl(path)
    orig = text

    if "com.android.alarm.permission.SET_ALARM" not in text:
        text = replace_once(
            text,
            '    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />',
            '    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />\n'
            '    <uses-permission android:name="com.android.alarm.permission.SET_ALARM" />',
            "AndroidManifest: SET_ALARM-oikeus herätyksille"
        )
    else:
        print("  [OK - jo sovellettu] AndroidManifest: SET_ALARM-oikeus")

    manifest_components = """        <provider
            android:name="androidx.core.content.FileProvider"
            android:authorities="${applicationId}.fileprovider"
            android:exported="false"
            android:grantUriPermissions="true">
            <meta-data
                android:name="android.support.FILE_PROVIDER_PATHS"
                android:resource="@xml/file_paths" />
        </provider>

        <service
            android:name=".QuickStampTileService"
            android:exported="true"
            android:icon="@drawable/ic_qs_tile"
            android:label="Pikaleimaus"
            android:permission="android.permission.BIND_QUICK_SETTINGS_TILE">
            <intent-filter>
                <action android:name="android.service.quicksettings.action.QS_TILE" />
            </intent-filter>
        </service>

        <receiver
            android:name=".ShiftWidgetProvider"
            android:exported="true"
            android:label="Vuorovahti">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
            </intent-filter>
            <meta-data
                android:name="android.appwidget.provider"
                android:resource="@xml/widget_shift_provider" />
        </receiver>

    </application>"""

    if "QuickStampTileService" not in text:
        text = replace_once(
            text,
            "    </application>",
            manifest_components,
            "AndroidManifest: FileProvider, QuickStampTileService ja ShiftWidgetProvider"
        )
    else:
        print("  [OK - jo sovellettu] AndroidManifest: FileProvider, TileService ja Widget")

    if text != orig:
        write_text_keep_nl(path, text, nl)
        return True
    return False


